DROP TABLE IF EXISTS timetable;
DROP TABLE IF EXISTS course;
DROP TABLE IF EXISTS lecturer;
DROP TABLE IF EXISTS lab;
DROP TABLE IF EXISTS class;
DROP TABLE IF EXISTS session;
CREATE TABLE session (sessioncode VARCHAR(16) PRIMARY KEY, session_name VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE department (departmentcode VARCHAR(64) PRIMARY KEY, departmentname VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE class (classcode VARCHAR(64) PRIMARY KEY, departmentcode VARCHAR(64) NOT NULL, FOREIGN KEY (departmentcode) REFERENCES department(departmentcode)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE course (coursecode VARCHAR(64) PRIMARY KEY, coursename VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE lecturer (lecturercode VARCHAR(64) PRIMARY KEY, lecturername VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE lab (labname VARCHAR(255) PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE timetable (ttid VARCHAR(8) NOT NULL, coursecode VARCHAR(64) NOT NULL, lecturercode VARCHAR(64) NOT NULL, labname VARCHAR(255) NOT NULL, classcode VARCHAR(64) NOT NULL, sessioncode VARCHAR(16) NOT NULL, PRIMARY KEY (ttid, coursecode, lecturercode, labname, classcode, sessioncode), KEY idx_timetable_class_session (classcode, sessioncode), CONSTRAINT fk_timetable_course FOREIGN KEY (coursecode) REFERENCES course(coursecode), CONSTRAINT fk_timetable_lecturer FOREIGN KEY (lecturercode) REFERENCES lecturer(lecturercode), CONSTRAINT fk_timetable_lab FOREIGN KEY (labname) REFERENCES lab(labname), CONSTRAINT fk_timetable_class FOREIGN KEY (classcode) REFERENCES class(classcode), CONSTRAINT fk_timetable_session FOREIGN KEY (sessioncode) REFERENCES session(sessioncode)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
